contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount, uint256 priceInput) public payable {
        // Drive c through the public entry `positionFee`.
        // Read the fees and oracle price that the fee computation depends on.
        UFixed18 makerFee = c.makerFee();
        UFixed18 takerFee = c.takerFee();
        UFixed18 positionFee_ = c.positionFee();
        IOracleProvider.OracleVersion memory ov = c.currentVersion();
        Fixed18 oraclePrice = ov.price;
        UFixed18 amount_ = UFixed18.wrap(amount);
        Fixed18 absPrice = Fixed18Lib.abs(oraclePrice);

        UFixed18 expectedMaker = amount_.mul(UFixed18.from(absPrice)).mul(makerFee);
        UFixed18 expectedTaker = amount_.mul(UFixed18.from(absPrice)).mul(takerFee);
